    int i = lo, j = hi;
    while (i <= j) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i <= j) {
            std::swap(a[i], a[j]);
            i++; j--;
        }
    }
    if (lo < j)   naiveQuickSort(a, lo, j);
    if (i < hi)   naiveQuickSort(a, i, hi);
}

